script:
frappe.listview_settings['Lead'] = {
    hide_name_column: true,
    hide_assign_col: true,
    hide_sharing_col: true,
    formatters: {
        whatsapp_icon: function(val, df, doc) {
            if (doc.phone) {
                let phone = doc.phone.replace(/\D/g,'');
                return `<a href="https://wa.me/${phone}" target="_blank" onclick="event.stopPropagation();">
                    <i class="fa fa-whatsapp text-success" style="font-size: 1.5em; cursor: pointer;"></i>
                </a>`;
            }
            return "";
        },
        owner: function(val) {
            let user = frappe.user_info(val);
            return user ? user.fullname : val;
        }
    }
};

// Force hide columns via DOM if needed on render
frappe.ui.form.on('Lead', {
    refresh: function(frm) {
        // Logic for form if needed
    }
});

